import java.util.Map;
import java.util.HashMap;
import java.util.List;

// Strategy pattern: the booking service does not care HOW a seat's price
// is decided, only that calling getPrice(seat) returns a number
interface PricingStrategy {
    double getPrice(Seat seat);
}

// Concrete strategy: a fixed price per seat type, no demand awareness
class StandardPricingStrategy implements PricingStrategy {
    @Override
    public double getPrice(Seat seat) {
        if (seat.getType() == SeatType.PREMIUM) {
            return 350.0; // premium seats cost more
        }
        return 200.0; // regular seats cost the base price
    }
}

// One specific screening of a movie, holding every seat that belongs to it
class Show {
    private String id;               // this show's identifier
    private Map<String, Seat> seats; // seat id -> that seat's object

    Show(String id, List<Seat> seatList) {
        this.id = id;
        this.seats = new HashMap<>();
        for (Seat seat : seatList) {
            seats.put(seat.getId(), seat); // index every seat by its id for O(1) lookup
        }
    }

    Seat getSeat(String seatId) {
        return seats.get(seatId); // returns null if the id does not exist on this show
    }
}

