#include <unordered_map>
#include <vector>
#include <string>
using namespace std;

// Strategy pattern: the booking service does not care HOW a seat's price
// is decided, only that calling getPrice(seat) returns a number
class PricingStrategy {
public:
    virtual double getPrice(Seat& seat) = 0;
    virtual ~PricingStrategy() {}
};

// Concrete strategy: a fixed price per seat type, no demand awareness
class StandardPricingStrategy : public PricingStrategy {
public:
    double getPrice(Seat& seat) override {
        if (seat.type == SeatType::PREMIUM) {
            return 350.0; // premium seats cost more
        }
        return 200.0; // regular seats cost the base price
    }
};

// One specific screening of a movie, holding every seat that belongs to it
class Show {
private:
    string id;                          // this show's identifier
    unordered_map<string, Seat> seats;  // seat id -> that seat's object

public:
    Show(string id, vector<Seat> seatList) : id(id) {
        for (auto& seat : seatList) {
            seats.insert({seat.id, seat}); // index every seat by its id for O(1) lookup
        }
    }

    Seat* getSeat(string seatId) {
        auto it = seats.find(seatId);
        if (it == seats.end()) return nullptr; // does not exist on this show
        return &(it->second); // return a pointer so callers can mutate the real seat
    }
};

