import java.util.List;
import java.util.ArrayList;

// Observer pattern: anything that wants to react to a booking outcome implements this
interface BookingObserver {
    void onBookingConfirmed(String bookingId, List<String> seatIds, double totalPrice);
    void onBookingFailed(List<String> seatIds, String reason);
}

// One concrete observer: simply prints every booking outcome to the console
class ConsoleBookingObserver implements BookingObserver {
    @Override
    public void onBookingConfirmed(String bookingId, List<String> seatIds, double totalPrice) {
        // report the booking id, exactly which seats, and the final price
        System.out.println("Booking " + bookingId + " confirmed for seats " + seatIds + ", total: " + totalPrice);
    }

    @Override
    public void onBookingFailed(List<String> seatIds, String reason) {
        // report which seats were requested and exactly why it failed
        System.out.println("Booking failed for seats " + seatIds + ": " + reason);
    }
}

// Orchestrates the whole booking flow: check availability, lock, price, confirm
public class BookingService {
    private Show show;                          // the show seats are being booked on
    private PricingStrategy pricingStrategy;     // however prices are decided
    private List<BookingObserver> observers = new ArrayList<>(); // everyone watching for outcomes
    private int bookingCounter = 0;              // used to generate readable booking ids

    public BookingService(Show show, PricingStrategy pricingStrategy) {
        this.show = show;
        this.pricingStrategy = pricingStrategy;
    }

    public void addObserver(BookingObserver observer) {
        observers.add(observer); // register a new observer, does not replace existing ones
    }

    // Attempts to book every seat in seatIds as one atomic operation.
    // Returns the new booking id on success, or null if the booking failed
    public String bookSeats(List<String> seatIds) {
        // Step 1: every single requested seat must actually exist and be AVAILABLE
        for (String seatId : seatIds) {
            Seat seat = show.getSeat(seatId);
            if (seat == null || seat.getStatus() != SeatStatus.AVAILABLE) {
                String reason = "Seat " + seatId + " is not available"; // exact reason for the failure
                for (BookingObserver observer : observers) {
                    observer.onBookingFailed(seatIds, reason);
                }
                return null; // fail fast, nothing has been locked or charged yet
            }
        }

        // Step 2: every check passed, lock every seat so nobody else can grab them mid-checkout
        for (String seatId : seatIds) {
            show.getSeat(seatId).setStatus(SeatStatus.LOCKED);
        }

        // Step 3: total the price across every requested seat
        double totalPrice = 0;
        for (String seatId : seatIds) {
            totalPrice += pricingStrategy.getPrice(show.getSeat(seatId));
        }

        // Step 4: "process payment" here in a real system, always succeeds in this demo

        // Step 5: payment succeeded, seats move from LOCKED to permanently BOOKED
        for (String seatId : seatIds) {
            show.getSeat(seatId).setStatus(SeatStatus.BOOKED);
        }

        bookingCounter++; // used to make each booking id unique and readable
        String bookingId = "BKG-" + bookingCounter;
        for (BookingObserver observer : observers) {
            observer.onBookingConfirmed(bookingId, seatIds, totalPrice);
        }
        return bookingId; // hand the new booking id back to the caller
    }
}

