// helper to print a vector of seat ids as "[R1, R2]"
string joinSeatIds(vector<string>& seatIds) {
    string result = "[";
    for (size_t i = 0; i < seatIds.size(); i++) {
        result += seatIds[i];
        if (i + 1 < seatIds.size()) result += ", ";
    }
    result += "]";
    return result;
}

