#include <iostream>
#include <vector>
#include <string>
#include <unordered_map>
using namespace std;

enum class SeatType { REGULAR, PREMIUM };
enum class SeatStatus { AVAILABLE, LOCKED, BOOKED };

class Seat {
public:
    string id;
    SeatType type;
    SeatStatus status;

    Seat(string id, SeatType type) : id(id), type(type), status(SeatStatus::AVAILABLE) {}
};

class ScreenLayoutFactory {
public:
    static vector<Seat> createLayout(int regularCount, int premiumCount) {
        vector<Seat> seats;
        for (int i = 1; i <= regularCount; i++) {
            seats.push_back(Seat("R" + to_string(i), SeatType::REGULAR));
        }
        for (int i = 1; i <= premiumCount; i++) {
            seats.push_back(Seat("P" + to_string(i), SeatType::PREMIUM));
        }
        return seats;
    }
};

class PricingStrategy {
public:
    virtual double getPrice(Seat& seat) = 0;
    virtual ~PricingStrategy() {}
};

class StandardPricingStrategy : public PricingStrategy {
public:
    double getPrice(Seat& seat) override {
        if (seat.type == SeatType::PREMIUM) return 350.0;
        return 200.0;
    }
};

class Show {
private:
    string id;
    unordered_map<string, Seat> seats;

public:
    Show(string id, vector<Seat> seatList) : id(id) {
        for (auto& seat : seatList) {
            seats.insert({seat.id, seat});
        }
    }

    Seat* getSeat(string seatId) {
        auto it = seats.find(seatId);
        if (it == seats.end()) return nullptr;
        return &(it->second);
    }
};

class BookingObserver {
public:
    virtual void onBookingConfirmed(string bookingId, vector<string> seatIds, double totalPrice) = 0;
    virtual void onBookingFailed(vector<string> seatIds, string reason) = 0;
    virtual ~BookingObserver() {}
};

string joinSeatIds(vector<string>& seatIds) {
    string result = "[";
    for (size_t i = 0; i < seatIds.size(); i++) {
        result += seatIds[i];
        if (i + 1 < seatIds.size()) result += ", ";
    }
    result += "]";
    return result;
}

class ConsoleBookingObserver : public BookingObserver {
public:
    void onBookingConfirmed(string bookingId, vector<string> seatIds, double totalPrice) override {
        cout << "Booking " << bookingId << " confirmed for seats " << joinSeatIds(seatIds) << ", total: " << totalPrice << endl;
    }

    void onBookingFailed(vector<string> seatIds, string reason) override {
        cout << "Booking failed for seats " << joinSeatIds(seatIds) << ": " << reason << endl;
    }
};

class BookingService {
private:
    Show& show;
    PricingStrategy* pricingStrategy;
    vector<BookingObserver*> observers;
    int bookingCounter;

public:
    BookingService(Show& show, PricingStrategy* pricingStrategy)
        : show(show), pricingStrategy(pricingStrategy), bookingCounter(0) {}

    void addObserver(BookingObserver* observer) {
        observers.push_back(observer);
    }

    string bookSeats(vector<string> seatIds) {
        for (auto& seatId : seatIds) {
            Seat* seat = show.getSeat(seatId);
            if (seat == nullptr || seat->status != SeatStatus::AVAILABLE) {
                string reason = "Seat " + seatId + " is not available";
                for (auto listener : observers) {
                    listener->onBookingFailed(seatIds, reason);
                }
                return "";
            }
        }

        for (auto& seatId : seatIds) {
            show.getSeat(seatId)->status = SeatStatus::LOCKED;
        }

        double totalPrice = 0;
        for (auto& seatId : seatIds) {
            totalPrice += pricingStrategy->getPrice(*show.getSeat(seatId));
        }

        for (auto& seatId : seatIds) {
            show.getSeat(seatId)->status = SeatStatus::BOOKED;
        }

        bookingCounter++;
        string bookingId = "BKG-" + to_string(bookingCounter);
        for (auto listener : observers) {
            listener->onBookingConfirmed(bookingId, seatIds, totalPrice);
        }
        return bookingId;
    }
};

int main() {
    // Factory pattern builds the seating layout: 2 regular seats, 1 premium seat
    vector<Seat> seatList = ScreenLayoutFactory::createLayout(2, 1); // R1, R2, P1

    Show show("SHOW-1", seatList);
    StandardPricingStrategy pricing;
    BookingService bookingService(show, &pricing);
    ConsoleBookingObserver observer;
    bookingService.addObserver(&observer); // print every outcome

    bookingService.bookSeats({"R1", "R2"}); // both available, succeeds
    bookingService.bookSeats({"R1", "P1"}); // R1 already booked, fails

    return 0;
}
